import org.junit.jupiter.api.AfterEach;
import java.io.ByteArrayOutputStream;
import java.io.PrintStream;
import static org.junit.jupiter.api.Assertions.*;

class LogRoleTests {
    private DefaultLogger logger;
    private final ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
    private final PrintStream originalOut = System.out;

    @BeforeEach
    void setUp() {
        logger = new DefaultLogger();
        System.setOut(new PrintStream(outputStream));
    }

    @AfterEach
    void tearDown() {
        System.setOut(originalOut);
    }

    @Test
    void testLogRoleWhenEnabled() {
        logger.enableLog(true);
        String[] roles = {"admin", "user", "guest"};

        logger.logRole(roles);

        String output = outputStream.toString().trim();
        assertTrue(output.contains("Roles:"));
        assertTrue(output.contains("admin"));
        assertTrue(output.contains("user"));
        assertTrue(output.contains("guest"));
    }

    @Test
    void testLogRoleWhenDisabled() {
        logger.enableLog(false);
        String[] roles = {"admin", "user"};

        logger.logRole(roles);

        String output = outputStream.toString().trim();
        assertTrue(output.isEmpty());
    }

    @Test
    void testLogRoleWithEmptyArray() {
        logger.enableLog(true);
        String[] roles = {};

        logger.logRole(roles);

        String output = outputStream.toString().trim();
        assertEquals("Roles:", output);
    }

    @Test
    void testLogRoleWithSingleRole() {
        logger.enableLog(true);
        String[] roles = {"admin"};

        logger.logRole(roles);

        String output = outputStream.toString().trim();
        assertEquals("Roles: admin", output);
    }

    @Test
    void testLogRoleWithNullArray() {
        logger.enableLog(true);

        logger.logRole(null);

        String output = outputStream.toString().trim();
        assertTrue(output.contains("Roles: null"));
    }

    @Test
    void testLogRoleWithMultipleRoles() {
        logger.enableLog(true);
        String[] roles = {"role1", "role2", "role3", "role4", "role5"};

        logger.logRole(roles);

        String output = outputStream.toString().trim();
        assertTrue(output.contains("Roles:"));
        for (String role : roles) {
            assertTrue(output.contains(role));
        }
    }

    @Test
    void testLogRoleWithSpecialCharacters() {
        logger.enableLog(true);
        String[] roles = {"admin@domain", "user-name", "role with spaces"};

        logger.logRole(roles);

        String output = outputStream.toString().trim();
        assertTrue(output.contains("Roles:"));
        assertTrue(output.contains("admin@domain"));
        assertTrue(output.contains("user-name"));
        assertTrue(output.contains("role with spaces"));
    }
}

