        if ("".equals(line)) {
            return;
        }

        if (line.charAt(0) == '#') {
            return;
        }

        String[] tokens = splitCommaDelimited(line);

        String key = tokens[0];
        String sec = key.substring(0, 1);
        Map<String, Assertion> astMap = model.model.get(sec);
        if(astMap == null) {
            return;
        }
        Assertion ast = astMap.get(key);
        if(ast == null) {
