        int child2Index = collectedRoles.indexOf("child2");
        int matched1Index = collectedRoles.indexOf("matched1");
        int matched2Index = collectedRoles.indexOf("matched2");

        assertTrue(child1Index >= 0);
        assertTrue(child2Index >= 0);
        assertTrue(matched1Index >= 0);
        assertTrue(matched2Index >= 0);

        // Direct roles should be processed before matched roles' sub-roles
        assertTrue(child1Index < matched1Index || child2Index < matched1Index);
    }

    @Test
    void testRangeRolesWithMultipleMatchedRoles() {
        Role anotherMatched = new Role("anotherMatched");
        rootRole.addMatch(anotherMatched);

        List<String> collectedRoles = new ArrayList<>();
        Consumer<Role> collector = role -> collectedRoles.add(role.getName());
        rootRole.rangeRoles(collector);

        assertEquals(5, collectedRoles.size());
        assertTrue(collectedRoles.contains("child1"));
        assertTrue(collectedRoles.contains("child2"));
        assertTrue(collectedRoles.contains("matched1"));
        assertTrue(collectedRoles.contains("matched2"));
        assertTrue(collectedRoles.contains("anotherMatched"));
    }

    @Test
    void testRangeRolesWithSelfReferencingRole() {
        // Test that circular references don't cause infinite loops
        Role circularRole = new Role("circular");
        circularRole.addRole(circularRole);

        List<String> collectedRoles = new ArrayList<>();
        Consumer<Role> collector = role -> {
            collectedRoles.add(role.getName());
            // Prevent infinite loop by limiting collection size
            if (collectedRoles.size() > 10) {
                throw new RuntimeException("Possible infinite loop detected");
            }
        };

        circularRole.rangeRoles(collector);

        // Should process the role itself
        assertEquals(1, collectedRoles.size());
        assertEquals("circular", collectedRoles.get(0));
    }
}

