    void testMatchWithCaseInsensitiveMatchingFunc() {
        BiPredicate<String, String> caseInsensitiveFunc = (str, pattern) ->
            str != null && pattern != null && str.equalsIgnoreCase(pattern);

        roleManager = new DefaultRoleManager(10, caseInsensitiveFunc, null);

        assertTrue(roleManager.match("TEST", "test"));
        assertTrue(roleManager.match("Test", "test"));
        assertTrue(roleManager.match("test", "TEST"));
        assertFalse(roleManager.match("test", "different"));
    }

